def compute(vars):
    market_price_per_share = vars["Market Price Per Share"]
    total_shares_outstanding = vars["Total Shares Outstanding"]
    market_capitalization = market_price_per_share * total_shares_outstanding
    return {
        "value": market_capitalization,
        "trace": {
            "Market Price Per Share": market_price_per_share,
            "Total Shares Outstanding": total_shares_outstanding,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "USD"
            }
        }
    }
